from capture import *
with scene('24-configuration-audit-backups','05-audit','Filter category changes and inspect evidence','Audit filters narrow the record to a particular entity, action, actor, or date range. Here the Recoverable Category filter shows our category creation, update, and deletion. Expand Before and after to inspect recorded values where available. The audit trail identifies changes; reviewers still need to interpret whether each change matches an approved business decision.', 'Training retention'):
 goto('/audit');select('Entity','Recoverable Category');click('button','Filter');click('generic','Before / after')
with scene('24-configuration-audit-backups','06-backup','Create a server backup and understand readiness','Create Backup packages the database and payment and request attachments on the application server. The page then lists the backup and its readiness status. Files present is a useful check, but it is not evidence that a restore works. Configuration and external secrets are managed separately, so a complete recovery plan includes those operational dependencies.', 'Operator restore command'):
 goto('/backups');click('button','Create Backup')
with scene('24-configuration-audit-backups','07-recovery','Read the operator recovery procedure','Expand the operator restore command and review the recovery procedure. A real recovery should first be tested into a separate database and attachment directory, with totals, records, and downloads checked. Production restoration replaces newer changes and requires the application to be stopped. This lesson creates a backup; it does not claim that a restore test has been performed.', 'Restore safely with your operator'):
 click('generic','Operator restore command');call('mousewheel','0','380')
